const REQUEST_HASH_PATTERN=/^[a-f0-9]{64}$/u;function createWorkerLedgerInputValidation(e){return{required:(t,n)=>{if(typeof t!==`string`||!t.trim())throw new Error(`${e} ${n} must be a non-empty string`);return t.trim()},integer:(t,n,r=0)=>{if(typeof t!==`number`||!Number.isSafeInteger(t)||t<r)throw new Error(`${e} ${n} must be a ${r===0?`non-negative`:`positive`} integer`);return t},requestHash:t=>{if(typeof t!==`string`||!REQUEST_HASH_PATTERN.test(t))throw new Error(`${e} request hash must be lowercase SHA-256 hex`);return t}}}export{createWorkerLedgerInputValidation as t};